import json
T = {}
for a, b in [(3, 7), (7, 12), (5, 9)]:
    T[a] = b
def chase(a, H, A):
    last = -1
    for _ in range(H):
        if a not in T:
            return last
        r = T[a]
        if r in A:
            return r
        last, a = r, r
    return last
print(json.dumps({"get3": T[3], "get5": T[5], "two_step_from_3": chase(3, 2, [12, 9])}))
